import {parseGoogleDriveLink} from './drive-link.mjs';
export function initAdminWizard({form,maxVideoBytes=50*1024*1024}) {
 if(!form)return null;
 const doc=form.ownerDocument,signalController=new AbortController(),signal=signalController.signal;
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const make=(tag,className)=>{const el=doc.createElement(tag);el.className=className;return el;};
 let step=0,quick=false,urls=[];
 const source=form.querySelector('#video-source'),sourceLabel=source.closest('label'),drive=form.querySelector('#drive-fields'),upload=form.querySelector('#upload-fields'),cover=form.elements.namedItem('cover').closest('label'),fileGrid=cover.parentElement;
 const info=[];for(const child of Array.from(form.children)){if(child===sourceLabel)break;info.push(child);}
 const steps=['Vídeo','Informações','Capa','Revisão'].map((title,index)=>{const section=make('section','wizard-step');section.dataset.wizardStep=String(index);const heading=make('h3','wizard-step-heading');heading.textContent=`${index+1}. ${title}`;section.append(heading);return section;});
 steps[0].append(sourceLabel,drive,upload);steps[1].append(...info);steps[2].append(cover);fileGrid.remove();
 const help=form.querySelector('p.hint');if(help)steps[3].append(help);
 const preview=make('div','wizard-preview'),refreshPreview=make('button','wizard-refresh-preview');refreshPreview.type='button';refreshPreview.textContent='Atualizar prévia';refreshPreview.addEventListener('click',()=>{if(!busy())previewMovie();},{signal});steps[3].append(refreshPreview,preview);
 const nav=make('nav','wizard-nav');nav.setAttribute('aria-label','Etapas para adicionar vídeo');
 ['Vídeo','Informações','Capa','Revisão'].forEach((label,index)=>{const button=make('button','wizard-step-button');button.type='button';button.dataset.goStep=String(index);button.textContent=`${index+1} ${label}`;nav.append(button);});
 const mode=make('button','wizard-mode');mode.type='button';mode.id='wizard-quick';mode.textContent='Modo rápido: mostrar todos os campos';
 const note=make('p','wizard-note');note.setAttribute('role','status');note.setAttribute('aria-live','polite');
 const actions=form.querySelector('#save-button').parentElement,save=form.querySelector('#save-button');
 const previous=make('button','wizard-previous');previous.id='wizard-previous';previous.type='button';previous.textContent='Voltar';
 const next=make('button','primary wizard-next');next.id='wizard-next';next.type='button';next.textContent='Continuar';actions.prepend(previous,next);
 form.prepend(mode,nav,note,...steps);form.noValidate=true;
 const busy=()=>form.getAttribute('aria-busy')==='true';
 const clearUrls=()=>{for(const url of urls)URL.revokeObjectURL(url);urls=[];preview.querySelector('video')?.pause();preview.replaceChildren();};
 const objectUrl=file=>{const url=URL.createObjectURL(file);urls.push(url);return url;};
 function previewMovie(){clearUrls();const get=name=>form.elements.namedItem(name)?.value||'';const driveSource=source.value==='drive';const video=form.elements.namedItem('video').files?.[0],image=form.elements.namedItem('cover').files?.[0];const coverUrl=image?objectUrl(image):'assets/own-video.svg';const age=get('age');preview.innerHTML=`<div class="wizard-poster"><img src="${esc(coverUrl)}" alt="Prévia da capa"></div><div class="wizard-summary"><p class="eyebrow">Prévia do rascunho</p><h3>${esc(get('title')||'Seu título')}</h3><p class="wizard-facts">${esc(get('year')||'Ano não informado')} · ${esc(get('minutes')||'?')} min · ${esc(age==='L'?'Livre':age?age+' anos':'Classificação pendente')}</p><p>${esc(get('synopsis')||'Adicione uma descrição para apresentar seu vídeo.')}</p><p class="hint">${esc(get('genres'))}${get('director')?' · '+esc(get('director')):''}</p><p class="hint">Créditos: ${esc(get('credit')||'Não informados')}</p><span class="badge">Rascunho · ainda não publicado</span></div><div class="wizard-media"></div><p class="hint wizard-preview-notice">Salvar cria apenas um rascunho. A publicação precisa ser confirmada separadamente na lista de vídeos.</p>`;
 const media=preview.querySelector('.wizard-media');
 if(driveSource){try{const parsed=parseGoogleDriveLink(get('drive_url'));const button=make('button','wizard-play-preview');button.type='button';button.textContent='Pré-visualizar vídeo do Drive';const link=doc.createElement('a');link.href=parsed.shareUrl;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Abrir no Google Drive';media.append(button,link);button.addEventListener('click',()=>{if(busy())return;const frame=doc.createElement('iframe');frame.src=parsed.embedUrl;frame.title='Prévia do seu vídeo no Google Drive';frame.allow='fullscreen';frame.allowFullscreen=true;media.prepend(frame);button.remove();},{signal});}catch{media.textContent='Adicione um link válido na etapa Vídeo para pré-visualizar.';}}
 else if(video){const player=doc.createElement('video');player.controls=true;player.playsInline=true;player.preload='metadata';player.src=objectUrl(video);player.poster=coverUrl;media.append(player);}
 }
 function render({focus=false}={}){for(let i=0;i<steps.length;i++)steps[i].hidden=!quick&&i!==step;nav.hidden=quick;for(const button of nav.children){if(Number(button.dataset.goStep)===step)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');}previous.hidden=quick||step===0;next.hidden=quick||step===3;save.hidden=!quick&&step!==3;mode.textContent=quick?'Voltar ao passo a passo':'Modo rápido: mostrar todos os campos';note.textContent=quick?'Todos os campos estão disponíveis. Salvar continua criando somente um rascunho.':`Etapa ${step+1} de 4 · ${['Escolha de onde vem o vídeo.','Conte um pouco sobre o vídeo.','Escolha uma imagem ou continue sem capa.','Confira tudo antes de salvar.'][step]}`;if(quick||step===3)previewMovie();else clearUrls();if(focus&&!quick){steps[step].querySelector('h3').tabIndex=-1;steps[step].querySelector('h3').focus();}}
 function validate(index){const section=steps[index];for(const field of section.querySelectorAll('input,textarea,select')){if(field.disabled)continue;field.setCustomValidity('');if(field.required&&field.type!=='file'&&!String(field.value).trim())field.setCustomValidity('Preencha este campo.');if(index===0&&field.name==='drive_url'&&source.value==='drive'){try{parseGoogleDriveLink(field.value);}catch{field.setCustomValidity('Cole o link de um arquivo do Google Drive, não de uma pasta.');}}if(field.type==='file'&&field.files?.[0]){const file=field.files[0];if(field.name==='video'&&(!/\.mp4$/i.test(file.name)||(file.type&&file.type!=='video/mp4')||file.size>maxVideoBytes))field.setCustomValidity(`Escolha um MP4 de até ${Math.floor(maxVideoBytes/1024/1024)} MiB.`);if(field.name==='cover'&&(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)))field.setCustomValidity('Escolha uma capa JPG, PNG ou WebP de até 5 MiB.');}if(!field.checkValidity()){if(!quick){step=index;render();}field.reportValidity();field.focus();return false;}}return true;}
 function go(target){if(busy())return;if(target>step)for(let index=0;index<target;index++)if(!validate(index))return;step=target;render({focus:true});}
 nav.addEventListener('click',event=>{const button=event.target.closest('[data-go-step]');if(button)go(Number(button.dataset.goStep));},{signal});previous.addEventListener('click',()=>go(Math.max(0,step-1)),{signal});next.addEventListener('click',()=>go(Math.min(3,step+1)),{signal});mode.addEventListener('click',()=>{if(busy())return;quick=!quick;render({focus:!quick});},{signal});
 form.addEventListener('input',event=>{event.target.setCustomValidity?.('');},{signal});
 form.addEventListener('submit',event=>{if(busy()){event.preventDefault();event.stopImmediatePropagation();return;}if(!quick&&step<3){event.preventDefault();event.stopImmediatePropagation();go(step+1);return;}for(let index=0;index<3;index++)if(!validate(index)){event.preventDefault();event.stopImmediatePropagation();return;}},{capture:true,signal});
 form.addEventListener('reset',()=>{setTimeout(()=>{step=0;render();},0);},{signal});
 doc.defaultView?.addEventListener('pagehide',clearUrls,{signal});
 render();
 return {clearPreview:clearUrls,destroy(){signalController.abort();clearUrls();},getStep:()=>step};
}
